'use strict';
const KEY='louie-study-pages:'+new URL('.',location.href).pathname;
const subjects=['数据结构','计算机组成原理','操作系统','计算机网络','数学二','英语二','政治'];
const chapters=[['数据结构',['复杂度与递归','线性表','栈与队列','串与模式匹配','树与二叉树','图与遍历','查找与散列表','排序']],['计算机组成原理',['计算机系统概述','数据表示与运算','存储系统与Cache','指令系统','CPU与流水线','总线','输入输出系统']],['操作系统',['操作系统概述','进程与线程','同步互斥与信号量','调度与死锁','内存管理','虚拟内存与页面置换','文件系统','设备与I/O']],['计算机网络',['网络体系结构','物理层','数据链路层','网络层与IP','传输层与TCP','应用层']]];
const blank=()=>({version:1,settings:{school:'南京理工大学（可更换）',major:'计算机专硕 · 22408',date:'',budget:240,focus:25},tasks:[],errors:[],mastery:{},sessions:[],mocks:[],attempts:[]});
let db=blank(),storageOK=true;try{if(window.LouiePublicSite&&window.LouiePublished?.data){db=structuredClone(window.LouiePublished.data)}else if(window.LouieLocal?.data){db=window.LouieLocal.data}else if(!window.LouieLocal){const raw=localStorage.getItem(KEY);if(raw)db=JSON.parse(raw)}}catch(e){storageOK=false}
let page='today',filter='全部',timer=null,endAt=0,remaining=0,focusTask=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const plusDay=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){storageOK=false;toast('浏览器无法保存，请立即导出备份。')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const labels={today:'今日学习',knowledge:'专业课',errors:'错题与复习',mocks:'模考复盘',resources:'考研信息',settings:'目标与备份'};
function go(p){page=labels[p]?p:'today';filter='全部';render()}
function render(){ $('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}">${v}</button>`).join('');$('#crumb').textContent=labels[page];$('#view').innerHTML=({today:todayView,knowledge:knowledgeView,errors:errorsView,mocks:mocksView,resources:resourcesView,math:mathView,settings:settingsView})[page](); if(!storageOK)$('#view').insertAdjacentHTML('afterbegin','<p class="note warn">本地存储不可用或读取失败。请导出已有数据，勿清理浏览器。</p>');}
const subjectLabel=s=>({'数学二':'数学','英语二':'英语','408':'专业课','408综合':'专业课综合','408复习':'专业课复习'}[s]||s);
const opts=(arr,sel)=>arr.map(x=>`<option value="${esc(x)}" ${x===sel?'selected':''}>${esc(subjectLabel(x))}</option>`).join('');
const due=()=>db.errors.filter(e=>e.due<=today());
function todayView(){const tasks=db.tasks.filter(t=>t.date===today()),done=tasks.filter(t=>t.done).length;const minutes=db.sessions.filter(t=>t.date===today()).reduce((a,t)=>a+t.minutes,0);const days=db.settings.date?Math.ceil((new Date(db.settings.date+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000):null;return `<div class="hero"><div><small>ONE THING AT A TIME / ${today()}</small><h1>少安排一点，真正学会一点。</h1><span>先做一组题，再决定下一段时间补哪里。</span></div><div>${days===null?'<small>考试日期待设置</small>':`<small>距自定考试日期</small><div class="stat">${days>=0?days+' 天':'日期已过'}</div>`}</div></div><div class="grid"><div class="card"><small>今日完成</small><div class="stat">${done}<small> / ${tasks.length}</small></div><small>未完成不自动堆到明天</small></div><div class="card"><small>到期复习</small><div class="stat">${due().length}<small> 条</small></div><button onclick="go('errors')">先复习到期错题 →</button></div><div class="card"><small>今日已记录专注</small><div class="stat">${minutes}<small> 分钟</small></div><small>以完成和复盘为准，不追求时长</small></div></div><div class="two"><section class="card"><div class="actions" style="justify-content:space-between"><h2>今天只抓关键任务</h2><button onclick="taskForm()">＋ 添加任务</button></div>${tasks.length?tasks.map(t=>`<div class="row"><div><label class="check"><input type="checkbox" ${t.done?'checked':''} onchange="toggleTask('${t.id}')"><span class="${t.done?'done':''}">${esc(t.title)}</span></label><small>${esc(subjectLabel(t.subject))} · ${t.minutes} 分钟</small></div><div class="actions"><button onclick="startFocus('${t.id}')">专注</button><button aria-label="删除任务" onclick="removeTask('${t.id}')">×</button></div></div>`).join(''):'<p class="empty">还没有任务。用一键计划开始，再按实际教材调整。</p>'}<div class="actions" style="margin-top:20px"><button class="primary" onclick="plan()">生成今天的限量计划</button><button onclick="carry()">选择补做往日任务</button></div><small>自动计划按可用时间限制总量；最多生成 4 项。已存在今日任务时不会重复添加。</small></section><section><div class="card"><span class="eyebrow">专注 / FOCUS</span><h2 style="margin-top:12px">留出一段不切换的时间</h2><p>计时结束后才记录完整时段。中断可按实际分钟登记。</p><button class="primary" onclick="startFocus()">开始 ${db.settings.focus} 分钟</button><button onclick="logTime()">补记学习</button></div><div class="card"><h2>两分钟收尾</h2><p class="muted">今天做错了什么？只记“为什么错”和“下次怎么判断”。不要抄整页解析。</p><button onclick="errorForm()">记录一条错题</button></div></section></div>`}
function taskForm(){show(`<h2>添加任务</h2><form id="taskForm"><label>任务与完成标准<input name="title" required maxlength="160" placeholder="例：完成链表10题，并重写错题步骤"></label><div class="formgrid"><label>科目<select name="subject">${opts(subjects)}</select></label><label>预计分钟<input type="number" name="minutes" min="5" max="480" value="30" required></label></div><label>日期<input type="date" name="date" value="${today()}" required></label><button class="primary">保存任务</button></form>`);$('#taskForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);db.tasks.push({id:uid(),title:d.get('title').trim(),subject:d.get('subject'),minutes:+d.get('minutes'),date:d.get('date'),done:false});save();closeModal();render()}}
function toggleTask(id){let t=db.tasks.find(x=>x.id===id);t.done=!t.done;save();render()}
function removeTask(id){db.tasks=db.tasks.filter(x=>x.id!==id);save();render()}
function plan(){if(db.tasks.some(t=>t.date===today()))return toast('今天已有任务，请手动调整，避免重复安排。');let budget=+db.settings.budget,ideas=[];if(due().length)ideas.push(['到期错题闭卷重做，口述判断依据','408复习',Math.min(20,budget)]);const weak=chapters.flatMap(([s,cs])=>cs.map(c=>({s,c,l:db.mastery[s+'|'+c]||0}))).sort((a,b)=>a.l-b.l)[0];ideas.push([`${weak.c}：读例题后闭卷做3～5题，标记薄弱点`,weak.s,Math.min(60,budget)]);const mathWeak=mathChapters.flatMap(x=>x[1]).sort((a,b)=>(db.mastery['数学二|'+a]||0)-(db.mastery['数学二|'+b]||0))[0];ideas.push(['数学 · '+mathWeak+'：做一组题，复算错题','数学二',60]);ideas.push(['英语：精读一篇阅读，复述错项原因','英语二',40]);let used=0;for(const [title,subject,proposed] of ideas){let minutes=Math.min(proposed,budget-used);if(minutes<5)break;db.tasks.push({id:uid(),title,subject,minutes,date:today(),done:false});used+=minutes}save();render();toast('已按时间预算安排；请按当前教材调整题目。')}
function carry(){const old=db.tasks.filter(t=>!t.done&&t.date<today());show(`<h2>选择确实要补做的任务</h2><p>不会自动结转。可以放弃不再必要的任务。</p>${old.length?old.map(t=>`<div class="row"><span>${esc(t.title)}<br><small>${t.date}</small></span><button onclick="moveTask('${t.id}')">移到今天</button></div>`).join(''):'<p>没有往日未完成任务。</p>'}`)}
function moveTask(id){db.tasks.find(t=>t.id===id).date=today();save();closeModal();render()}
function knowledgeView(){return `<h1>把“看过”变成“能做”</h1><p class="muted">这是复习导航，不替代当年官方大纲。掌握程度由你闭卷做题后自评。</p>${chapters.map(([s,cs])=>{const n=cs.filter(c=>(db.mastery[s+'|'+c]||0)===3).length;return `<section class="card"><h2>${s} <small>${n} / ${cs.length}</small></h2><div class="bar"><i style="width:${n/cs.length*100}%"></i></div>${cs.map(c=>`<div class="row"><span>${c}</span><select aria-label="${c}掌握程度" onchange="setMastery('${s}|${c}',this.value)">${['未开始','学过但不稳','能做基础题','已掌握'].map((v,i)=>`<option value="${i}" ${+(db.mastery[s+'|'+c]||0)===i?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</section>`}).join('')}`}
function setMastery(k,v){db.mastery[k]=+v;save();render()}
function errorsView(){const list=db.errors.filter(e=>(filter==='全部'||(filter==='到期'?e.due<=today():e.subject===filter)));return `<h1>错过的题，下次拿回来。</h1><p class="muted">先遮住答案重做，再评价记忆。重复失败会重新从 1 天开始。</p><div class="actions"><button class="primary" onclick="errorForm()">＋ 记错题 / 记忆卡</button><span class="tag">${due().length} 条到期 · ${db.errors.length} 条记录</span></div><div class="tabs">${['全部','到期',...subjects].map(s=>`<button class="${filter===s?'primary':''}" onclick="filter='${s}';render()">${esc(subjectLabel(s))}</button>`).join('')}</div>${list.length?list.sort((a,b)=>a.due.localeCompare(b.due)).map(e=>`<article class="card"><div class="actions"><span class="tag">${esc(subjectLabel(e.subject))}</span><small>${esc(e.chapter)} · 下次 ${e.due}</small></div><h3 style="margin-top:16px">${esc(e.title)}</h3><p style="white-space:pre-wrap">${esc(e.prompt)}</p><small>题目位置：${esc(e.source||'未填写')}</small><details><summary>已闭卷作答，查看纠错与答案</summary><p style="white-space:pre-wrap">${esc(e.answer)}</p><p>错因：${esc(e.reason)}</p><div class="actions"><button onclick="reviewError('${e.id}',false)">仍不会 · 明天再做</button><button class="primary" onclick="reviewError('${e.id}',true)">独立做对 · 安排下次</button></div></details><div class="actions"><button onclick="errorForm('${e.id}')">编辑</button><button onclick="deleteError('${e.id}')">删除</button></div></article>`).join(''):'<div class="card empty">这里还没有记录。做题遇到卡点时再添加，不需要先整理旧笔记。</div>'}`}
function errorForm(id){const e=db.errors.find(x=>x.id===id)||{};show(`<h2>${id?'编辑':'记录'}错题 / 记忆卡</h2><form id="errorForm"><div class="formgrid"><label>科目<select name="subject">${opts(subjects,e.subject)}</select></label><label>章节<input name="chapter" value="${esc(e.chapter)}"></label></div><label>卡点标题<input name="title" required maxlength="180" value="${esc(e.title)}" placeholder="例：Cache地址拆分漏算块内偏移"></label><label>题目 / 自问（支持直接粘贴文字）<textarea name="prompt" required>${esc(e.prompt)}</textarea></label><label>答案与下次判断步骤<textarea name="answer" required>${esc(e.answer)}</textarea></label><label>错因<select name="reason">${opts(['概念不清','计算失误','方法不会','审题遗漏','记忆遗忘'],e.reason)}</select></label><label>出处 / 页码 / 题号<input name="source" value="${esc(e.source)}" placeholder="例：手中习题册第32页第8题"></label><button class="primary">保存并安排复习</button></form>`);$('#errorForm').onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));if(id)Object.assign(e,d);else db.errors.push({...d,id:uid(),due:plusDay(1),level:0});save();closeModal();render();toast('已保存；新错题明天开始复习。')}}
function reviewError(id,pass){const e=db.errors.find(x=>x.id===id);e.level=pass?Math.min((e.level||0)+1,5):0;e.due=plusDay([1,3,7,14,30,60][e.level]);e.last=today();save();render();toast('下次复习：'+e.due)}
function deleteError(id){if(confirm('删除这条错题？建议先导出备份。')){db.errors=db.errors.filter(x=>x.id!==id);save();render()}}
function mocksView(){return `<h1>把一次模考，变成下一周的重点。</h1><p class="muted">记录真实得分与失分原因，不自动预测录取概率。408 训练可用 180 分钟、150 分为完整卷参数，按你手中试卷核对。</p><button class="primary" onclick="mockForm()">＋ 记录模考</button><div style="margin-top:20px">${db.mocks.length?db.mocks.slice().reverse().map(m=>`<div class="card"><div class="actions"><span class="tag">${esc(subjectLabel(m.subject))}</span><small>${m.date} · ${m.minutes} 分钟</small></div><h2 style="margin-top:14px">${esc(m.title)} <span style="float:right">${m.score} / ${m.total}</span></h2><p style="white-space:pre-wrap">${esc(m.review)}</p><button onclick="mockToTask('${m.id}')">把改进动作排进今天</button></div>`).join(''):'<div class="card empty">还没有模考记录。做完一套卷后花两分钟记录即可。</div>'}</div>`}
function mockForm(){show(`<h2>记录模考结果</h2><form id="mockForm"><label>试卷名称<input name="title" required placeholder="例：手中某年真题首次限时"></label><div class="formgrid"><label>科目<select name="subject">${opts(['408','数学二','英语二','政治'])}</select></label><label>日期<input type="date" name="date" value="${today()}" required></label><label>得分<input type="number" name="score" min="0" max="500" step="0.5" required></label><label>满分<input type="number" name="total" min="1" max="500" value="150" required></label><label>用时（分钟）<input type="number" name="minutes" min="1" max="600" value="180" required></label></div><label>失分原因 → 下一次具体动作<textarea name="review" required placeholder="例：页表计算丢6分 → 重做3题，逐步写出地址转换"></textarea></label><button class="primary">保存复盘</button></form>`);$('#mockForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(+d.score>+d.total)return toast('得分不能大于满分。');db.mocks.push({...d,id:uid()});save();closeModal();render()}}
function mockToTask(id){const m=db.mocks.find(x=>x.id===id);if(db.tasks.some(t=>t.mockId===id))return toast('已经生成过对应任务。');db.tasks.push({id:uid(),mockId:id,date:today(),title:m.review,subject:m.subject,minutes:30,done:false});save();toast('已加入今日任务。')}
const resources=[['报考核对','南京理工大学研究生招生网','https://gs.njust.edu.cn/zsw/','确认学院、专业代码、考试科目、招生与复试通知；换学校后更新目标，不迁移学习记录。','学校官方入口'],['报考核对','2027 年南理工招生简章与目录','https://gs.njust.edu.cn/zsw/ae/8b/c4587a372363/page.htm','用于核对目标专业当年要求；该年份不等于你的考试年份。不能假定所有计算机专业都考22408。','学校官方 · 2027招生'],['报考核对','2026 年南理工复试基本要求（历史）','https://gs.njust.edu.cn/_upload/article/files/bd/8d/81e74c9e48e9937e9b3a738dbab2/c6d44c10-0348-4edb-b5c3-145b798874f4.pdf','只用于理解往年学院与专业差异；复试线不是录取线，不外推今年。','学校官方 · 历史资料'],['数据结构','浙江大学《数据结构》','https://www.icourse163.org/course/ZJU-93001','只补当前不懂的知识点，例如树、图、排序；已能独立做题的部分可跳过视频。','中国大学MOOC · 课程方页面'],['报考核对','中国研究生招生信息网','https://yz.chsi.com.cn/','查看当年统考报名与考试通知、招生信息。以官方最新公告为准。','教育部指定研招平台']];
function resourcesView(){return `<h1>资料够用就好。</h1><p class="muted">核验日期：2026-11-09。已搜集的入口按用途筛选；外链需要联网，学习记录可离线使用。</p><div class="note">主线建议：每科一套主资料＋合法取得的历年真题。基础缺口再查教材或课程，不同时追多套课。本站不内置盗版教材或未授权真题。</div><div class="card"><h2>官方信息与补缺入口</h2>${resources.map(r=>`<div class="resource"><span class="tag">${r[0]}</span> <small>${r[4]}</small><h3 style="margin-top:8px"><a href="${r[2]}" target="_blank" rel="noopener noreferrer">${r[1]} ↗</a></h3><p>${r[3]}</p></div>`).join('')}</div><div class="card"><h2>四科补缺路线</h2><p><b>数据结构：</b>先会手推过程，再写核心算法；重点检查复杂度与边界条件。</p><p><b>组成原理：</b>数据表示 → 存储系统 → 指令与CPU → I/O；计算题先写单位、位数与公式。</p><p><b>操作系统：</b>进程同步、内存与文件系统；画状态、资源与地址转换过程。</p><p><b>计算机网络：</b>按层理解协议；子网、窗口与时延题先画图再计算。</p><small>以上为学习路线建议，知识范围与分值请核对报考年份正式大纲。本版未取得当年官方408大纲全文，不将第三方解读当作官方原文。</small></div><div class="card"><h2>公共课保持最小闭环</h2><p>数学二：做题与错题复算；英语二：真题阅读与错误选项分析；政治：按你的备考阶段安排。都可在每日任务、错题和模考里记录。</p><small>“22408”暂按你提供的信息设置，不代表已核验目标专业的考试科目。</small></div>`}
function settingsView(){return `<h1>你的节奏，保存在本地。</h1><p class="muted">更换学校不会清空408进度。不要为了填满数据占用学习时间。</p><div class="two"><div class="card"><h2>目标与时间预算</h2><form id="settingsForm"><label>目标学校<input name="school" value="${esc(db.settings.school)}" required maxlength="100"></label><label>专业与考试组合<input name="major" value="${esc(db.settings.major)}" required maxlength="100"></label><label>自定考试日期（确认官方日期后填写）<input type="date" name="date" value="${db.settings.date}"></label><label>每日可用于本网站计划的分钟<input type="number" min="20" max="720" name="budget" value="${db.settings.budget}" required></label><label>每段专注分钟<input type="number" min="1" max="180" name="focus" value="${db.settings.focus}" required></label><button class="primary">保存设置</button></form></div><div><div class="card"><h2>备份与恢复</h2><p>数据在当前浏览器内，不上传服务器。更换浏览器、清理网站数据或使用无痕模式可能丢失记录。</p><div class="actions"><button class="primary" onclick="exportData()">导出完整备份</button><button onclick="document.querySelector('#importFile').click()">从备份恢复</button><input id="importFile" type="file" accept="application/json,.json" hidden onchange="importData(this.files[0]);this.value='' "></div><small>恢复会替换当前数据；导入前会提示先备份。兼容旧版学习记录；新版完整备份包含附件。</small></div><div class="card"><h2>功能取舍</h2><p>保留：任务、专注、知识自评、间隔复习、模考复盘、资料入口、备份。</p><p>不增加：社交、积分、排行榜、信息流。没有接入AI服务，也不会把固定回复伪装成AI答疑。</p><button onclick="window.print()">打印 / 保存当前页为PDF</button></div></div></div>`}
function show(html){$('#modal').innerHTML=`<button style="float:right" aria-label="关闭" onclick="closeModal()">×</button>${html}`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if(timer){toast('专注计时仍在继续，可点击“继续专注”查看。')}$('#modal').close()}
function startFocus(id){if(timer){drawTimer();return}focusTask=id||null;remaining=(id?db.tasks.find(t=>t.id===id).minutes:db.settings.focus)*60;endAt=Date.now()+remaining*1000;timer=setInterval(tick,500);drawTimer()}
function drawTimer(){show(`<h2>${focusTask?esc(db.tasks.find(t=>t.id===focusTask)?.title||'专注学习'):'专注计时'}</h2><div class="timer" id="clock"></div><p class="muted">计时结束后记录实际分钟。</p><div class="actions"><button class="primary" onclick="finishFocus()">结束并记录</button><button onclick="stopFocus()">放弃本次</button></div>`);tick()}
function tick(){remaining=Math.max(0,Math.ceil((endAt-Date.now())/1000));if($('#clock'))$('#clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining===0){clearInterval(timer);timer=null;show('<h2>这一段结束了。</h2><p>请记录实际学习时间，完成后再决定是否继续。</p><button class="primary" onclick="finishFocus()">确认并记录</button>')}}
function stopFocus(){clearInterval(timer);timer=null;document.querySelector('#resumeFocus')?.remove();closeModal();render()}
function finishFocus(){clearInterval(timer);timer=null;document.querySelector('#resumeFocus')?.remove();const t=db.tasks.find(x=>x.id===focusTask);logTime(t)}
function logTime(task){show(`<h2>记录实际学习</h2><form id="timeForm"><label>科目<select name="subject">${opts(subjects,task?.subject)}</select></label><label>实际学习分钟<input name="minutes" type="number" min="1" max="720" value="${task?.minutes||db.settings.focus}" required></label>${task?'<label class="check"><input name="done" type="checkbox" style="width:auto">同时标记任务已完成</label>':''}<button class="primary">保存记录</button></form>`);$('#timeForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);db.sessions.push({date:today(),subject:d.get('subject'),minutes:+d.get('minutes')});if(task&&d.get('done'))task.done=true;save();closeModal();render()}}
function exportData(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Louie学习站备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validData(d){const str=x=>typeof x==='string',num=x=>typeof x==='number'&&Number.isFinite(x),record=x=>x&&typeof x==='object'&&!Array.isArray(x),date=x=>str(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x);return record(d)&&d.version===1&&record(d.settings)&&str(d.settings.school)&&str(d.settings.major)&&(d.settings.date===''||date(d.settings.date))&&num(d.settings.budget)&&d.settings.budget>=20&&d.settings.budget<=720&&num(d.settings.focus)&&d.settings.focus>=1&&d.settings.focus<=180&&record(d.mastery)&&Object.values(d.mastery).every(x=>Number.isInteger(x)&&x>=0&&x<=3)&&['tasks','errors','sessions','mocks','attempts'].every(k=>Array.isArray(d[k])&&d[k].length<50000)&&d.tasks.every(t=>record(t)&&/^[a-zA-Z0-9-]{1,100}$/.test(t.id)&&str(t.title)&&str(t.subject)&&date(t.date)&&num(t.minutes)&&t.minutes>0&&t.minutes<=480&&typeof t.done==='boolean')&&d.errors.every(e=>record(e)&&/^[a-zA-Z0-9-]{1,100}$/.test(e.id)&&str(e.title)&&str(e.prompt)&&str(e.answer)&&str(e.subject)&&str(e.chapter)&&str(e.reason)&&date(e.due)&&Number.isInteger(e.level)&&e.level>=0&&e.level<=5)&&d.sessions.every(s=>record(s)&&date(s.date)&&str(s.subject)&&num(s.minutes)&&s.minutes>0&&s.minutes<=720)&&d.mocks.every(m=>record(m)&&/^[a-zA-Z0-9-]{1,100}$/.test(m.id)&&str(m.title)&&str(m.subject)&&date(m.date)&&str(m.review)&&Number.isFinite(+m.score)&&+m.score>=0&&+m.total>0&&+m.total>=+m.score&&+m.total<=500&&+m.minutes>0&&+m.minutes<=600)&&d.attempts.every(a=>record(a)&&date(a.date)&&typeof a.correct==='boolean'&&Number.isInteger(a.qid)&&a.qid>=0&&a.qid<27)}
async function importData(file){if(!file)return;if(file.size>10000000)return toast('文件超过10MB，未导入。');try{const d=JSON.parse(await file.text());if(!validData(d))throw Error('invalid');if(!confirm('恢复将替换当前全部学习记录。请确认已导出当前备份，继续恢复？'))return;db=d;save();render();toast('恢复完成。')}catch(e){toast('备份格式不完整或版本不匹配，未修改现有数据。')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
function openFocusSettings(){
  show(`<h2>调整专注时长</h2><form id="focusSettingsForm">
    <label>默认专注时长（分钟）<input type="number" min="1" max="180" name="focus" value="${db.settings.focus}" required></label>
    <button class="primary">保存时长</button>
  </form>`);
}

document.addEventListener('submit', async event => {
  const form = event.target;
  if (!['focusSettingsForm', 'examSettingsForm'].includes(form.id)) return;
  event.preventDefault();
  const fields = new FormData(form);
  const previous = db.settings;
  const updated = { ...db.settings };
  if (form.id === 'examSettingsForm') {
    updated.school = String(fields.get('school') || '').trim();
    updated.major = String(fields.get('major') || '').trim();
    updated.date = String(fields.get('date') || '');
    updated.budget = Number(fields.get('budget'));
    if (!updated.school || !updated.major || !Number.isInteger(updated.budget) || updated.budget < 20 || updated.budget > 720) {
      toast('请填写学校、考试组合和有效的计划预算。');
      return;
    }
  } else {
    updated.focus = Number(fields.get('focus'));
    if (!Number.isInteger(updated.focus) || updated.focus < 1 || updated.focus > 180) {
      toast('请输入 1 至 180 分钟的专注时长。');
      return;
    }
  }
  db.settings = updated;
  if (await save()) {
    if (form.id === 'focusSettingsForm' && form.isConnected) $('#modal').close();
    render();
    toast('设置已保存。');
  } else if (db.settings === updated) {
    db.settings = previous;
  }
});
$('#modal').addEventListener('close',()=>{if(timer&&!document.querySelector('#resumeFocus')){const b=document.createElement('button');b.id='resumeFocus';b.textContent='继续专注';b.style='position:fixed;right:24px;bottom:24px';b.onclick=drawTimer;document.body.appendChild(b)}else if(!timer)document.querySelector('#resumeFocus')?.remove()});
// Personal library and learning log. File bodies live in IndexedDB, not localStorage.
db.materials??=[];db.progress??=[];
Object.assign(labels,{library:'电子资料',tracking:'时间与进度'});
let librarySubject='全部',librarySearch='',libraryStatus='全部';
const previousTodayView=todayView;
todayView=function(){const html=previousTodayView();const start=html.indexOf('<div class="grid">');const active=db.materials.filter(m=>m.status==='学习中');return html.slice(0,start)+`<div class="quicklinks"><button onclick="go('library')">▤ 电子资料 <small>${db.materials.length} 份</small></button><button onclick="go('tracking')">◷ 时间与进度 <small>${active.length} 份学习中</small></button><button onclick="sessionForm()">＋ 记录刚完成的学习</button></div>`+html.slice(start)};
const originalRender=render;
render=function(){if(page==='library'||page==='tracking'){const p=page;page='today';originalRender();page=p;$('#crumb').textContent=labels[p];$('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}">${v}</button>`).join('');$('#view').innerHTML=p==='library'?libraryView():trackingView()}else originalRender();$('#nav').innerHTML=['today','library','tracking','knowledge','math','errors','mocks','resources','settings'].map(k=>`<button data-page="${k}" class="${page===k?'active':''}"><span class="navdot"></span>${labels[k]}</button>`).join('')};
let vaultPromise;
function vault(){if(!vaultPromise)vaultPromise=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('浏览器不支持本地附件存储'));const req=indexedDB.open(KEY+':files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}).catch(e=>{vaultPromise=null;throw e});return vaultPromise}
async function fileOp(mode,key,value){const v=await vault();return new Promise((resolve,reject)=>{const tx=v.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files');const req=mode==='get'?store.get(key):mode==='put'?store.put(value,key):store.delete(key);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('文件存储中断'))})}
const materialSubjects=['数学二','英语二','政治','数据结构','计算机组成原理','操作系统','计算机网络','408综合','其他'];
const percent=m=>m.total>0?Math.min(100,Math.round(m.current/m.total*100)):0;
function libraryView(){const list=db.materials.filter(m=>(!window.LouiePersonal||window.LouiePersonal.matches(m))&&(librarySubject==='全部'||m.subject===librarySubject)&&(libraryStatus==='全部'||m.status===libraryStatus)&&[m.title,m.tags,m.note].some(x=>String(x||'').toLowerCase().includes(librarySearch.toLowerCase())));return `<div class="pagehead"><div><span class="eyebrow">YOUR KNOWLEDGE, ORGANIZED</span><h1>电子资料</h1><p class="muted">资料各归其位，学习随时继续。</p></div><button class="primary" onclick="materialForm()">＋ 收纳资料</button></div><div class="library-layout"><section class="card categories"><h3>按科目整理</h3>${['全部',...(window.LouiePersonal?.subjects()||materialSubjects)].map(s=>`<button class="category ${librarySubject===s?'selected':''}" data-library-subject="${esc(s)}">${esc(subjectLabel(s))}<small>${db.materials.filter(m=>(!window.LouiePersonal||window.LouiePersonal.matches(m))&&(s==='全部'||m.subject===s)).length}</small></button>`).join('')}</section><section><div class="card library-toolbar"><input aria-label="搜索资料" placeholder="搜索标题、标签、笔记…" value="${esc(librarySearch)}" id="librarySearch"><select aria-label="筛选资料状态" onchange="libraryStatus=this.value;render()">${opts(['全部','待学习','学习中','已完成'],libraryStatus)}</select></div><div class="materials">${list.length?list.slice().reverse().map(m=>`<article class="card material"><div class="actions" style="justify-content:space-between"><span class="filebadge">${m.fileId?'FILE':'LINK'}</span><span class="tag">${esc(subjectLabel(m.subject))}</span></div><h2>${esc(m.title)}</h2><small>${esc(m.tags||'未添加标签')} · ${esc(m.status)}</small><div class="bar"><i style="width:${percent(m)}%"></i></div><div class="actions" style="justify-content:space-between"><small>${m.current} / ${m.total||'未设'} ${esc(m.unit)} </small><b>${percent(m)}%</b></div>${m.note?`<p class="material-note">${esc(m.note)}</p>`:''}<div class="actions"><button class="primary" onclick="openMaterial('${m.id}')">${m.fileId?'打开文件':'打开链接'} ↗</button><button onclick="progressForm('${m.id}')">更新进度</button><button onclick="materialForm('${m.id}')" aria-label="编辑${esc(m.title)}">编辑</button></div><small class="filemeta">${esc(m.fileName||'外部网址')} ${m.size?' · '+(m.size/1024/1024).toFixed(1)+' MB':''}</small></article>`).join(''):'<div class="card empty"><div class="empty-icon">↥</div><h2>给你的学习资料安一个家</h2><p>上传本地 PDF、文档、图片，或收藏课程和网盘链接。<br>先放正在使用的资料，不必一次整理全部。</p><button class="primary" onclick="materialForm()">添加第一份资料</button></div>'}</div><p class="muted" style="font-size:12px">附件保存在当前浏览器，未上传网络。PDF与图片可用浏览器打开，其他格式可下载后打开。请通过“目标与备份”定期导出含附件备份。</p></section></div>`}
function materialForm(id){const m=db.materials.find(x=>x.id===id)||{};show(`<h2>${id?'编辑资料':'收纳一份资料'}</h2><form id="materialForm"><label>资料标题<input name="title" required maxlength="160" value="${esc(m.title)}" placeholder="输入资料名称"></label><div class="formgrid"><label>科目<select name="subject">${opts(materialSubjects,m.subject)}</select></label><label>标签<input name="tags" maxlength="180" value="${esc(m.tags)}" placeholder="按用途添加标签"></label></div>${id?'<p class="muted">保留原附件或链接。更换来源请另建资料。</p>':'<label>上传文件（单份最多200MB）<input name="file" type="file"></label><p class="muted">或填写外部链接，二选一即可。</p><label>外部链接<input name="url" type="url" placeholder="https://…"></label>'}<div class="formgrid"><label>总进度量<input name="total" type="number" min="0" max="1000000" value="${m.total||0}" required></label><label>单位<select name="unit">${opts(['页','节','题','章','小节','首','次','组','分钟'],m.unit)}</select></label></div><small>总量暂不清楚可填0，之后再设置。</small><label>备注<textarea name="note" maxlength="3000" placeholder="例如：只补不熟的章节，不必从头看">${esc(m.note)}</textarea></label><div class="actions"><button class="primary" id="materialSave">保存资料</button>${id?`<button type="button" onclick="deleteMaterial('${id}')">删除资料</button>`:''}</div><p id="fileError" role="status"></p></form>`);$('#materialForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=$('#materialSave');button.disabled=true;let fileId;try{const file=f.get('file'),url=String(f.get('url')||'').trim();const data={trackId:f.get('trackId')||'exam',title:String(f.get('title')).trim(),subject:f.get('subject'),tags:f.get('tags'),total:+f.get('total'),unit:f.get('unit'),note:f.get('note')};if(!data.title)throw Error('请填写资料标题');if(id){if(data.total>0&&data.total<m.current)throw Error('总量不能小于已完成量');Object.assign(m,data);m.status=m.total>0&&m.current>=m.total?'已完成':m.current>0?'学习中':'待学习'}else{if(!(file&&file.size)&&!url)throw Error('请选择文件或填写链接');if(file&&file.size&&url)throw Error('文件和链接只需选一种');const item={...data,id:uid(),current:0,status:'待学习',created:today()};if(file&&file.size){if(file.size>200*1024*1024)throw Error('单份文件不能超过200MB');fileId=uid();await fileOp('put',fileId,file);Object.assign(item,{fileId,fileName:file.name,size:file.size,mime:file.type})}else{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))throw Error('只支持http或https链接');item.url=u.href}db.materials.push(item)}save();closeModal();render();toast('资料已收纳')}catch(error){if(fileId)await fileOp('delete',fileId).catch(()=>{});$('#fileError').textContent=error.message}finally{button.disabled=false}}}
async function openMaterial(id){const m=db.materials.find(x=>x.id===id);if(m.url){window.open(m.url,'_blank','noopener,noreferrer');return}try{const blob=await fileOp('get',m.fileId);if(!blob)throw Error('附件未找到，请从含附件备份恢复，或重新添加资料');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';if(!['application/pdf','image/png','image/jpeg','image/gif','image/webp','text/plain'].includes(blob.type)&&!/^audio\/|^video\//.test(blob.type))a.download=m.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){toast(e.message)}}
async function deleteMaterial(id){if(!confirm('删除这份资料及本地附件？进度历史保留。建议先导出备份。'))return;const m=db.materials.find(x=>x.id===id);try{if(m.fileId)await fileOp('delete',m.fileId);db.materials=db.materials.filter(x=>x.id!==id);save();closeModal();render()}catch(e){toast('删除失败，记录已保留。')}}
function progressForm(id){const m=db.materials.find(x=>x.id===id);show(`<h2>更新学习进度</h2><p>${esc(m.title)}</p><form id="progressForm"><label>已完成到（${esc(m.unit)}）<input name="current" type="number" min="0" max="${m.total||1000000}" value="${m.current}" required></label><label>本次学到了什么 / 下次从哪里继续<textarea name="note" maxlength="2000" placeholder="一句话就够"></textarea></label><button class="primary">保存进度</button></form>`);$('#progressForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),current=+f.get('current');db.progress.push({id:uid(),trackId:m.trackId||'exam',materialId:id,title:m.title,subject:m.subject,date:today(),previous:m.current,current,unit:m.unit,note:f.get('note')});m.current=current;m.status=m.total>0&&current>=m.total?'已完成':current>0?'学习中':'待学习';save();closeModal();render();toast('进度已更新')}}
function trackingView(){const scoped=window.LouieProjectScope?.sessions()||db.sessions,days=Array.from({length:7},(_,i)=>plusDay(i-6)),week=scoped.filter(s=>days.includes(s.date)),sum=ss=>ss.reduce((a,s)=>a+s.minutes,0),daily=days.map(d=>sum(scoped.filter(s=>s.date===d))),max=Math.max(60,...daily),total=sum(scoped);return `<div class="pagehead"><div><span class="eyebrow">STEADY STEPS, REAL PROGRESS</span><h1>时间与进度</h1><p class="muted">看见投入，也记住下一步。</p></div><button class="primary" onclick="sessionForm()">＋ 记录学习</button></div><div class="grid"><div class="card"><small>今日学习</small><div class="stat">${sum(scoped.filter(s=>s.date===today()))}<small> 分钟</small></div></div><div class="card"><small>最近7天</small><div class="stat">${(sum(week)/60).toFixed(1)}<small> 小时</small></div></div><div class="card"><small>累计学习</small><div class="stat">${(total/60).toFixed(1)}<small> 小时</small></div></div></div><div class="two"><section class="card"><h2>近7天学习节奏</h2><div class="weekchart">${days.map((d,i)=>`<div class="daycolumn"><span>${daily[i]}m</span><div class="columntrack"><i style="height:${daily[i]/max*100}%"></i></div><small>${d.slice(5)}</small></div>`).join('')}</div><small>仅统计已记录的实际分钟，不含未确认的计时。</small></section><section class="card"><h2>这周时间花在哪里</h2>${[...new Set(week.map(s=>s.subject))].map(s=>{const mins=sum(week.filter(x=>x.subject===s));return `<div class="row"><span>${esc(subjectLabel(s))}</span><b>${mins} 分钟</b></div>`}).join('')||'<p class="empty">记录第一段学习后，这里会显示科目分布。</p>'}</section></div><section class="card"><h2>正在学习的资料</h2>${db.materials.filter(m=>m.status!=='已完成').map(m=>`<div class="row"><div><b>${esc(m.title)}</b><br><small>${esc(subjectLabel(m.subject))} · ${m.current}/${m.total||'未设总量'} ${esc(m.unit)}</small></div><button onclick="progressForm('${m.id}')">更新进度</button></div>`).join('')||'<p class="empty">到电子资料区添加正在使用的资料，记录页数或课程节数。</p>'}</section><section class="card"><h2>学习记录</h2>${scoped.length?db.sessions.map((s,i)=>({s,i})).filter(x=>window.LouieProjectScope?.matches(x.s)??true).sort((a,b)=>b.s.date.localeCompare(a.s.date)||b.i-a.i).slice(0,60).map(({s,i})=>`<div class="row"><div><b>${esc(subjectLabel(s.subject))} · ${s.minutes} 分钟</b><br><small>${s.date} ${esc(s.note||'')}</small></div><div class="actions"><button onclick="sessionForm(${i})">编辑</button><button onclick="deleteSession(${i})">删除</button></div></div>`).join(''):'<p class="empty">没有虚拟示例记录。你的第一段真实学习会从这里开始。</p>'}<small>显示最近60条；完整记录包含在备份里。</small></section><section class="card"><h2>进度足迹</h2>${db.progress.filter(p=>window.LouieProjectScope?.matches(p)??true).slice(-30).reverse().map(p=>`<div class="row"><div><b>${esc(p.title)}</b><br><small>${p.date} · ${p.previous} → ${p.current} ${esc(p.unit)}</small><p>${esc(p.note)}</p></div></div>`).join('')||'<p class="empty">更新资料进度时会自动留下一条记录。</p>'}</section>`}
function sessionForm(index){const s=index===undefined?{date:today(),subject:'数学二',minutes:30,note:''}:db.sessions[index];show(`<h2>${index===undefined?'记录一段学习':'修改学习记录'}</h2><form id="sessionForm"><div class="formgrid"><label>日期<input name="date" type="date" max="${today()}" value="${s.date}" required></label><label>科目<select name="subject">${opts([...new Set([...subjects,'408综合','408复习',s.subject])],s.subject)}</select></label></div><label>实际分钟<input name="minutes" type="number" min="1" max="720" value="${s.minutes}" required></label><label>学习内容 / 完成进度<textarea name="note" maxlength="2000" placeholder="例如：高数第三讲，完成例题1～8">${esc(s.note||'')}</textarea></label><button class="primary">保存记录</button></form>`);$('#sessionForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.minutes=+data.minutes;if(index===undefined)db.sessions.push(data);else db.sessions[index]=data;save();closeModal();render();toast('学习记录已保存')}}
function deleteSession(i){if(confirm('删除这条学习时间记录？')){db.sessions.splice(i,1);save();render()}}
const oldValidData=validData;
validData=function(d){if(!oldValidData(d))return false;const id=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x),str=x=>typeof x==='string',n=x=>Number.isInteger(x)&&x>=0&&x<=1000000;return (d.materials===undefined||(Array.isArray(d.materials)&&d.materials.length<=10000&&d.materials.every(m=>id(m.id)&&str(m.title)&&str(m.subject)&&str(m.unit)&&n(m.total)&&n(m.current)&&(!m.total||m.current<=m.total)&&['待学习','学习中','已完成'].includes(m.status)&&(m.fileId?id(m.fileId)&&str(m.fileName):str(m.url)&&/^https?:\/\//i.test(m.url)))))&&(d.progress===undefined||(Array.isArray(d.progress)&&d.progress.length<=50000&&d.progress.every(p=>id(p.id)&&str(p.title)&&str(p.subject)&&str(p.unit)&&n(p.previous)&&n(p.current)&&str(p.date)&&str(p.note))))};
const downloadJSON=(data,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
exportData=async function(){try{toast('正在打包记录与本地附件…');const files=[];for(const m of db.materials){if(m.fileId){const blob=await fileOp('get',m.fileId);if(!blob)throw Error('资料“'+m.title+'”附件缺失，无法生成完整备份');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)});files.push({id:m.fileId,data,name:m.fileName,type:blob.type})}}const teacher=localDisk?await diskRequest('/api/teacher/export').then(r=>r.json()):undefined;downloadJSON({format:'louie-study-backup',version:2,db,files,teacher},'Louie学习站完整备份-'+today()+'.json');toast('完整备份已生成，包含'+files.length+'个附件')}catch(e){toast('备份失败：'+e.message)}};
importData=async function(file){if(!file)return;try{if(file.size>350*1024*1024)throw Error('备份超过350MB');const raw=JSON.parse(await file.text()),data=raw.format==='louie-study-backup'?raw.db:raw;if(!validData(data))throw Error('记录结构不完整或版本不匹配');data.materials??=[];data.progress??=[];data.infoChecks??={};const files=raw.files||[],decoded=[];for(const m of data.materials.filter(x=>x.fileId)){const f=files.find(x=>x.id===m.fileId);if(!f||typeof f.data!=='string'||!/^data:[^,]*;base64,/.test(f.data))throw Error('备份缺少附件：'+m.title);const b64=f.data.slice(f.data.indexOf(',')+1),bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));if(bytes.length>200*1024*1024)throw Error('附件过大');decoded.push({material:m,blob:new Blob([bytes],{type:f.type||'application/octet-stream'})})}if(raw.teacher&&localDisk)await diskRequest('/api/teacher/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:raw.teacher,validateOnly:true})});if(!confirm('恢复将替换当前学习记录和资料列表。请先导出当前完整备份，确认继续？'))return;const staged=[];try{for(const f of decoded){const next=uid();await fileOp('put',next,f.blob);staged.push(next);f.material.fileId=next}await persistCandidate(data)}catch(e){for(const id of staged)await fileOp('delete',id).catch(()=>{});throw e}db=data;if(raw.teacher&&localDisk){try{await diskRequest('/api/teacher/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:raw.teacher})});if(window.reloadTeacherAfterImport)await window.reloadTeacherAfterImport()}catch(error){render();toast('学习记录已恢复，老师记录未恢复：'+error.message);return}}render();toast('恢复完成，资料和学习记录已就位')}catch(e){toast('未恢复：'+e.message)}};
