function dateStatus(start,end){const now=Date.now();if(now<new Date(start+'T00:00:00+08:00').getTime())return '未开始';if(now>new Date(end+'T23:59:59+08:00').getTime())return '已结束';return '进行中'}
resourcesView=function(){if(!window.LouieExamInfo)return examInfoLoadingView();const d=window.LouieExamInfo,stale=!d.checkedAt||Date.now()-new Date(d.checkedAt+'T23:59:59+08:00')>7*86400000;const notices=d.notices.filter(n=>(infoCategory==='全部'||n.category===infoCategory)&&(infoYear==='全部'||String(n.year)===infoYear));const years=[...new Set([...d.notices.map(n=>String(n.year)),...d.scores.map(n=>String(n.year))])].sort().reverse();return `<div class="pagehead"><div><span class="eyebrow">ADMISSIONS / VERIFIED SOURCES</span><h1>考研信息</h1><p class="muted">只保留会影响报名、考试和择校的重要信息。</p></div><button onclick="location.reload()">重新载入已更新内容</button></div><div class="note ${stale?'warn':''}"><b>${d.schedule.active?'每日 09:00 查询官方来源':'定期查询待启用'}</b> · 最近成功核验：${esc(d.checkedAt||'尚无')}（北京时间）${stale?' · 已超过7天，使用前请查原文':''}<br><small>定期查询由本机Codex执行，需电脑开机、联网并保持应用运行；网页自身不会在关闭后抓取信息。刷新仅载入已核验内容，不代表已重新联网核验。</small></div><div class="note">当前资料范围：<b>南京理工大学 · 计算机科学与工程学院相关专硕</b>，以及全国统考。你的当前目标：${esc(db.settings.school)}。更换目标后这些校级历史信息仍保留，不会自动视为新学校的要求。报考年份尚未确认，以下每条均标明招生年份。</div><div class="tabs">${['全部','公告','报名与考试','报考要求','复试与录取','分数线'].map(s=>`<button class="${infoCategory===s?'primary':''}" onclick="infoCategory='${s}';render()">${esc(subjectLabel(s))}</button>`).join('')}<select aria-label="招生年份" onchange="infoYear=this.value;render()">${opts(['全部',...years],infoYear)}</select></div>${infoCategory==='全部'||infoCategory==='报名与考试'?`<section class="card"><h2>报名与考试时间轴</h2><p class="muted">招生年份 ≠ 日历年份。例如2027年招生的初试安排在2026年；报考点要求只适用于对应报考点。</p>${d.timeline.filter(x=>infoYear==='全部'||String(x.year)===infoYear).map(t=>`<div class="row"><div><span class="tag">${t.year}招生 · ${dateStatus(t.start,t.end)}</span><h3 style="margin:9px 0">${esc(t.title)}</h3><small>${esc(t.start)}${t.start!==t.end?' ～ '+esc(t.end):''} · ${esc(t.scope)}</small><p>${esc(t.note)}</p>${infoLink(t.url)}</div></div>`).join('')||'<p class="empty">这一年份尚无已核验时间安排。</p>'}</section>`:''}${infoCategory==='全部'||infoCategory==='分数线'?scoreSection(d,infoYear):''}${infoCategory==='全部'||infoCategory==='报考要求'?`<section class="card"><h2>报考核对清单</h2><p class="muted">勾选仅表示你已核对，不代表系统判定你具备报考资格。</p>${d.requirements.filter(x=>infoYear==='全部'||String(x.year)===infoYear).map(r=>`<div class="row"><div><label class="check"><input type="checkbox" ${db.infoChecks?.[r.id]?'checked':''} onchange="checkInfo('${r.id}',this.checked)"><span>${esc(r.title)}</span></label><p>${esc(r.note)}</p><small>${r.year}招生 · ${esc(r.scope)} · </small>${infoLink(r.url)}</div></div>`).join('')||'<p class="empty">这一年份暂无已整理核对项。</p>'}</section>`:''}<section class="card"><h2>官方公告与入口 <small>${notices.length} 条</small></h2>${notices.map(n=>`<article class="resource"><div class="actions"><span class="tag">${esc(n.category)}</span><small>${n.year}招生 · ${esc(n.published||'发布日期未单独核验')} · ${esc(n.scope)}</small></div><h3 style="margin-top:12px">${infoLink(n.url,esc(n.title)+' ↗')}</h3><p>${esc(n.summary)}</p><small>来源：${esc(n.source)} · 核验：${esc(n.checkedAt||d.checkedAt)}</small></article>`).join('')||'<p class="empty">当前条件没有公告。</p>'}</section><section class="card"><h2>最近核验记录</h2>${d.updates.slice(0,6).map(u=>`<div class="row"><small>${esc(u.date)}</small><span>${esc(u.text)}</span></div>`).join('')}<small>不能访问原文或不能确认统计口径的信息标为待核实，不用搜索摘要填造录取分数。</small></section>`};
function scoreSection(d,year){const scores=d.scores.filter(s=>year==='全部'||String(s.year)===year);return `<section class="card"><h2>历年分数 · 分清统计口径</h2><p class="muted">国家线、学校/学院复试线、拟录取最低初试分是三种不同指标；达到复试线不等于录取。</p><div class="scorecards">${scores.map(s=>`<article class="scorecard"><span class="eyebrow">${s.year} 年招生</span><div class="stat">${s.retest}<small> 分</small></div><b>复试总分线 · 非专项</b><p>${esc(s.school)}<br>${esc(s.college)}<br>${esc(s.program)}</p><small>原文口径：${esc(s.code)}<br>单科：${esc(s.single)}<br>拟录取最低分：${s.admittedMin==null?'待核实完整名单':s.admittedMin+'分'}<br>核验：${esc(s.checkedAt||d.checkedAt)}</small><p>${infoLink(s.url)}</p></article>`).join('')||'<p class="empty">该年份暂无已核验分数。</p>'}</div><details><summary>为什么没有直接显示“录取分数线”？</summary><p>拟录取最低初试分只能对完整公示名单按学院、专业、全/非全、统考/推免、专项/普通、一志愿/调剂分别筛选后统计。最低分也不是下一年的录取承诺。当前完整名单原文未核验通过，暂不填写。</p></details><div class="actions">${infoLink('https://gs.njust.edu.cn/zsw/4585/list.htm','南理工历年复试线入口 ↗')}${infoLink('https://yz.chsi.com.cn/zsgs/','研招信息公开平台 ↗')}</div><small>没有将学硕、人工智能专硕或其他学院的分数混入本组比较；历年考试科目变化也会影响可比性。</small></section>`}
